CREATE FUNCTION public.get_pivoted_lib_titles(prj integer) RETURNS TABLE(lib_titles text[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    col_list TEXT;
    dyn_sql TEXT;
BEGIN
    -- Build dynamic column list
    SELECT string_agg(
        format('MAX(CASE WHEN lib_id = %s THEN lib_title END)', lib_id),
        ', '
    )
    INTO col_list
    FROM (
        SELECT DISTINCT lib_id
        FROM libtbl2025
        WHERE prj_id = prj
        ORDER BY lib_id
    ) sub;

    -- Construct SQL to return as array (or individual columns if preferred)
    dyn_sql := format('SELECT ARRAY[%s] FROM libtbl2025 WHERE prj_id = %s;', col_list, prj);

    -- Execute and return
    RETURN QUERY EXECUTE dyn_sql;
END;
$$;


